        INSERT INTO persyaratan_legal(id_customer,catatan_kekurangan) VALUES(v_customer,X'496d706f72204441544120414b4150204b50522044414e20434153482e786c73782c2043415348202620434153482054454d504f2062617269732033312e204964656e746974617320637573746f6d65722062656c756d2074657273656469612e204265726b6173206c6567616c2062656c756d2064697665726966696b6173692e');
        SET v_legal=LAST_INSERT_ID();
    END IF;

    -- CASH & CASH TEMPO, baris 32, L-09
    IF (SELECT COUNT(*) FROM kavling_peta WHERE id_lokasi=v_loc AND kode_kavling=X'4c2d3039')<>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unit L-09 tidak ditemukan/duplikat';
    END IF;
    SELECT id INTO v_unit FROM kavling_peta WHERE id_lokasi=v_loc AND kode_kavling=X'4c2d3039' FOR UPDATE;
    IF (SELECT COUNT(*) FROM marketing_offline WHERE BINARY nama_marketing=BINARY X'4d2053414e545249204d41554c414e41')>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Nama marketing duplikat; periksa master';
    END IF;
    SET v_marketing=(SELECT id FROM marketing_offline WHERE BINARY nama_marketing=BINARY X'4d2053414e545249204d41554c414e41' LIMIT 1);
    IF v_marketing IS NULL THEN
        SET v_marketing_seq=v_marketing_seq+1;
        INSERT INTO marketing_offline(kode_marketing,nama_marketing,jenis_kelamin,pekerjaan,nama_bank,no_rekening,atas_nama,status,foto)
        VALUES(CONCAT('M-',LPAD(v_marketing_seq,GREATEST(4,LENGTH(v_marketing_seq)),'0')),X'4d2053414e545249204d41554c414e41',0,'','','','',1,'');
        SET v_marketing=LAST_INSERT_ID();
    END IF;
    IF (SELECT COUNT(*) FROM customer WHERE id_kavling=v_unit AND (stt_arsip=0 OR stt_arsip IS NULL))>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Lebih dari satu customer aktif L-09';
    END IF;
    SET v_customer=(SELECT id FROM customer WHERE id_kavling=v_unit AND (stt_arsip=0 OR stt_arsip IS NULL) LIMIT 1);
    IF v_customer IS NOT NULL THEN
        IF NOT EXISTS(SELECT 1 FROM customer WHERE id=v_customer AND BINARY nama_lengkap=BINARY X'416b626172' AND id_lokasi=v_loc AND jenis_pembelian=X'43617368204265727461686170' AND id_marketing=v_marketing AND id_status_progres=v_cash_status) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Customer existing L-09 berbeda; impor dibatalkan';
        END IF;
    ELSE
        SET v_customer_seq=v_customer_seq+1;
        INSERT INTO customer(kode_customer,id_lokasi,id_kavling,id_status_progres,nama_lengkap,id_marketing,jenis_pembelian,termin_x_cash_b,stt_arsip)
        VALUES(CONCAT('GDI-',LPAD(v_customer_seq,GREATEST(4,LENGTH(v_customer_seq)),'0')),v_loc,v_unit,v_cash_status,X'416b626172',v_marketing,X'43617368204265727461686170',NULL,0);
        SET v_customer=LAST_INSERT_ID();
    END IF;
    IF EXISTS(SELECT 1 FROM kavling_peta WHERE id=v_unit AND id_customer IS NOT NULL AND id_customer<>0 AND id_customer<>v_customer) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Relasi customer kavling L-09 berbeda';
    END IF;
    UPDATE kavling_peta SET id_customer=v_customer WHERE id=v_unit;
    IF (SELECT COUNT(*) FROM persyaratan_legal WHERE id_customer=v_customer)>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Persyaratan legal duplikat';
    END IF;
    SET v_legal=(SELECT id FROM persyaratan_legal WHERE id_customer=v_customer LIMIT 1);
    IF v_legal IS NULL THEN
        INSERT INTO persyaratan_legal(id_customer,catatan_kekurangan) VALUES(v_customer,X'496d706f72204441544120414b4150204b50522044414e20434153482e786c73782c2043415348202620434153482054454d504f2062617269732033322e204964656e746974617320637573746f6d65722062656c756d2074657273656469612e204265726b6173206c6567616c2062656c756d2064697665726966696b6173692e');
        SET v_legal=LAST_INSERT_ID();
    END IF;

    COMMIT;
    SELECT 'BERHASIL: blok I, 81 customer dan 53 akad sudah diproses; keuangan tidak diimpor' AS hasil;
END$$
CALL spl_import_20261112_akad_v1()$$
DROP PROCEDURE spl_import_20261112_akad_v1$$
DELIMITER ;
